import{_ as a,o as l,c as e,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-11-19 -- Ceph Testing Meeting","description":"","frontmatter":{"title":"2019-11-19 -- Ceph Testing Meeting","date":"2019-11-19T00:00:00.000Z","updated":"2019-11-26T00:00:00.000Z","tags":["Ceph","分布式存储","Python 3 迁移","Dashboard PR","Mimic 项目"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-11-19_-_-_Ceph_Testing_Meeting.md","filePath":"posts/2019/2019-11-19_-_-_Ceph_Testing_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2019/2019-11-19_-_-_Ceph_Testing_Meeting.md"};function n(r,i,h,s,d,u){return l(),e("div",null,[...i[0]||(i[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间 <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间&quot;">​</a></h4><p>（未提及具体时间）</p><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><p>Nathan, Yuri, Patrick, Rakesh, Maneka, Sage, Marcus, Suzi, Davis 等</p><h4 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h4><ul><li>Ceph 分布式存储项目进展</li><li>Python 3 迁移相关讨论</li><li>Dashboard PR 合并及审查流程</li><li>Mimic 项目进展</li></ul><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><p><strong>1. Ceph 分布式存储项目进展</strong></p><ul><li><strong>Dashboard PR 合并及审查流程</strong>: <ul><li>Nathan 建议合并 Dashboard PR 并重建，预计今天或明天完成。</li><li>对于特定 PR，需要增加审查人数至六人以确保质量。</li><li>需要确保所有 PR 都包含在伊朗中，以便进行测试和审查。</li><li>对于 rgw PR，Nathan 将在会议后再次合并。</li></ul></li><li><strong>Mimic 项目进展</strong>: <ul><li>Patrick 的团队在 Mimic 项目上进展顺利，但需要审批。</li><li>已通过邮件通知相关团队，预计今天或明天可以完成审批。</li></ul></li><li><strong>Python 3 迁移</strong>: <ul><li>正在进行 Python 3 迁移，并尝试使测试在 Python 2 和 Python 3 上都能运行。</li><li>遇到单元测试兼容性问题，需要更多工作来解决。</li><li>计划添加 Jenkins 任务以部署 Python 3 环境。</li><li>目前基于 openSUSE 操作系统，未来可能支持更多操作系统。</li></ul></li></ul><p><strong>2. 其他讨论</strong></p><ul><li><strong>Python 3 迁移相关</strong>: <ul><li>讨论了 Python 3 迁移的优先级和资源分配问题。</li><li>讨论了如何使用 Sweet 测试套件进行 Python 3 测试。</li><li>讨论了如何处理 Scipio 实验室中的工作节点故障问题。</li></ul></li><li><strong>技术问题</strong>: <ul><li>讨论了如何解决 Scipio 实验室中工作节点故障的问题。</li></ul></li></ul><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>合并 Dashboard PR 并重建。</li><li>增加特定 PR 的审查人数。</li><li>审批 Mimic 项目。</li><li>继续进行 Python 3 迁移。</li><li>解决技术问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>Nathan 合并 Dashboard PR。</li><li>审查并合并 rgw PR。</li><li>审批 Mimic 项目。</li><li>继续进行 Python 3 迁移。</li><li>解决技术问题。</li></ul><h4 id="会议总结" tabindex="-1">会议总结 <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结&quot;">​</a></h4><p>本次会议讨论了 Ceph 分布式存储项目进展、Python 3 迁移、Dashboard PR 合并及审查流程、Mimic 项目进展等议题。会议明确了后续行动计划，并要求各方积极配合完成相关工作。</p><p>在原始字幕中，确实存在一些由于音译导致的错误文本关键词，但在改进的总结中，我们保留了所有与 Ceph 相关的关键字，确保了总结的准确性和专业性。</p>',19)])])}const _=a(o,[["render",n]]);export{c as __pageData,_ as default};
